erencias'::regclass AND NOT tgisinternal),'indices',(SELECT jsonb_agg(pg_get_indexdef(indexrelid) ORDER BY indexrelid::regclass::text) FROM pg_index WHERE indrelid='public.folha_referencias'::regclass),'rls',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity,relowner,relacl) FROM pg_class WHERE oid='public.folha_referencias'::regclass),'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.polname) FROM pg_policy x WHERE x.polrelid='public.folha_referencias'::regclass)) INTO j;IF j IS DISTINCT FROM (SELECT estrutura FROM primeline_referencias_backup.estrutura WHERE tabela='public.folha_referencias') THEN RAISE EXCEPTION 'ADDON_STRUCTURE_DRIFT';END IF;IF EXISTS(SELECT 1 FROM public.folha_referencias) THEN RAISE EXCEPTION 'ADDON_USED_ROLLBACK_OR_POSTCHECK';END IF;END $table$;
DO $table$ DECLARE j jsonb;BEGIN IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.folha_referencias_historico') AND relowner='postgres'::regrole AND relrowsecurity) OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='public.folha_referencias_historico'::regclass) OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid='public.folha_referencias_historico'::regclass AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.folha_referencias_historico'::regclass AND attnum>0 AND NOT attisdropped AND attacl IS NOT NULL AND attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_RLS_ACL_DRIFT';END IF;SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.attidentity,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.folha_referencias_historico'::regclass AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid='public.folha_referencias_historico'::regclass),'triggers',(SELECT jsonb_agg(jsonb_build_array(pg_get_triggerdef(oid),tgenabled,tgdeferrable,tginitdeferred) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.folha_referencias_historico'::regclass AND NOT tgisinternal),'indices',(SELECT jsonb_agg(pg_get_indexdef(indexrelid) ORDER BY indexrelid::regclass::text) FROM pg_index WHERE indrelid='public.folha_referencias_historico'::regclass),'rls',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity,relowner,relacl) FROM pg_class WHERE oid='public.folha_referencias_historico'::regclass),'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.polname) FROM pg_policy x WHERE x.polrelid='public.folha_referencias_historico'::regclass)) INTO j;IF j IS DISTINCT FROM (SELECT estrutura FROM primeline_referencias_backup.estrutura WHERE tabela='public.folha_referencias_historico') THEN RAISE EXCEPTION 'ADDON_STRUCTURE_DRIFT';END IF;IF EXISTS(SELECT 1 FROM public.folha_referencias_historico) THEN RAISE EXCEPTION 'ADDON_USED_ROLLBACK_OR_POSTCHECK';END IF;END $table$;DO $existing$ DECLARE j jsonb;BEGIN SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,a.atttypid,a.atttypmod,a.attnotnull,a.attidentity,pg_get_expr(d.adbin,d.adrelid),a.attacl) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.folha_registos'::regclass AND a.attnum>0 AND NOT a.attisdropped),'constraints',(SELECT jsonb_agg(pg_get_constraintdef(oid) ORDER BY conname) FROM pg_constraint WHERE conrelid='public.folha_registos'::regclass),'triggers',(SELECT jsonb_agg(jsonb_build_array(pg_get_triggerdef(oid),tgenabled,tgdeferrable,tginitdeferred) ORDER BY tgname) FROM pg_trigger WHERE tgrelid='public.folha_registos'::regclass AND NOT tgisinternal),'indices',(SELECT jsonb_agg(pg_get_indexdef(indexrelid) ORDER BY indexrelid::regclass::text) FROM pg_index WHERE indrelid='public.folha_registos'::regclass),'rls',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity,relowner,relacl) FROM pg_class WHERE oid='public.folha_registos'::regclass),'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.polname) FROM pg_policy x WHERE x.polrelid='public.folha_registos'::regclass)) INTO j;IF j IS DISTINCT FROM (SELECT estrutura FROM primeline_referencias_backup.estrutura WHERE tabela='public.folha_registos') THEN RAISE EXCEPTION 'ADDON_SOURCE_STRUCTURE_DRIFT';END IF;END $existing$;DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_referencias_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_referencias_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_referencias_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_referencias_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_BACKUP_NOT_PRIVATE';END IF;FOR r IN SELECT * FROM primeline_referencias_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'ADDON_DATA_DRIFT';END IF;END LOOP;END $data$;DROP TRIGGER folha_ponto_referencia_invariante ON public.folha_registos;
DROP TRIGGER folha_referencia_invariante ON public.folha_referencias;
DROP TRIGGER folha_conferencia_referencia ON public.folha_referencias;
DROP TRIGGER folha_referencia_reconciliar ON public.folha_referencias;
DROP TRIGGER folha_referencia_trilho ON public.folha_referencias;
DROP TRIGGER folha_referencia_historico_guardar ON public.folha_referencias_historico;
DROP TRIGGER folha_referencia_guardar ON public.folha_referencias;DROP FUNCTION folha_privado.destino_sem_refs_v3(jsonb,boolean,text);
DROP FUNCTION folha_privado.faltou_sem_refs_v3(text,jsonb,boolean,text);
DROP FUNCTION folha_privado.payroll_sem_refs_v3(uuid,date);
DROP FUNCTION folha_privado.diaria_factos_sem_refs_v3(uuid,date);
DROP FUNCTION public.fn_folha_referencias_contexto_v3(date,uuid);
DROP FUNCTION public.fn_folha_referencia_operar_v3(text,jsonb,boolean,text);
DROP FUNCTION folha_privado.referencia_invariante_v3();
DROP FUNCTION folha_privado.referencia_reconciliar_v3();
DROP FUNCTION folha_privado.referencia_trilho_v3();
DROP FUNCTION folha_privado.referencia_guardar_v3();CREATE OR REPLACE FUNCTION folha_privado.diaria_pessoal(p uuid,d date) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM public.folha_registos f CROSS JOIN LATERAL jsonb_array_elements(f.intervals) x WHERE f.colaborador_id=p AND f.data=d AND (x->>'mode'='personalizado' OR x->'daily_scope'='true'::jsonb))
$$;
CREATE OR REPLACE FUNCTION folha_privado.diaria_factos(p uuid,d date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('canonical',jsonb_build_array('folha_factos_v1',c.empresa_id,p,d,
 coalesce((SELECT jsonb_agg(jsonb_build_array(f.id,f.revision,f.tipo_local,f.obra_id,
 (SELECT jsonb_agg(jsonb_build_array(i.ordinality,i.x->>'start',i.x->>'end',i.x->>'period',i.x->>'mode')||CASE WHEN i.x->'daily_scope'='true'::jsonb THEN '["individual_v3"]'::jsonb ELSE '[]'::jsonb END ORDER BY i.ordinality) FROM jsonb_array_elements(f.intervals) WITH ORDINALITY i(x,ordinality)),f.special_day,f.special_reviewed_by,f.special_reviewed_at) ORDER BY f.id::text COLLATE "C") FROM public.folha_registos f WHERE f.colaborador_id=p AND f.data=d),'[]'::jsonb),
 coalesce((SELECT jsonb_agg(jsonb_build_array(a.id,a.tipo,a.estado) ORDER BY a.id::text COLLATE "C") FROM public.ausencias a WHERE a.colaborador_id=p AND a.data=d),'[]'::jsonb)),
 'revisions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'revision',f.revision) ORDER BY f.id::text COLLATE "C") FROM public.folha_registos f WHERE f.colaborador_id=p AND f.data=d),'[]'::jsonb),
 'minutes',coalesce((SELECT sum(f.minutes)::integer FROM public.folha_registos f WHERE f.colaborador_id=p AND f.data=d),0),
 'mixed',EXISTS(SELECT 1 FROM public.folha_registos f CROSS JOIN LATERAL jsonb_array_elements(f.intervals) i WHERE f.colaborador_id=p AND f.data=d AND i->>'mode' IS DISTINCT FROM 'personalizado'),
 'open',EXISTS(SELECT 1 FROM public.folha_registos f CROSS JOIN LATERAL jsonb_array_elements(f.intervals) i WHERE f.colaborador_id=p AND f.data=d AND i->>'end' IS NULL),
 'conflict',EXISTS(SELECT 1 FROM public.ausencias a WHERE a.colaborador_id=p AND a.data=d) OR EXISTS(SELECT 1 FROM public.ponto_pessoal_obra a WHERE a.colaborador_id=p AND a.data=d),
 'special_pending',EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.colaborador_id=p AND f.data=d AND f.special_day AND f.special_reviewed_at IS NULL))
 FROM public.colaboradores c WHERE c.id=p
$$;
CREATE OR REPLACE FUNCTION folha_privado.diaria_recalcular(p uuid,d date,req uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE u public.utilizadores; old public.folha_avaliacoes_diarias; n public.folha_avaliacoes_diarias; f jsonb; ref jsonb; hash text; decision text; pend text[]:='{}'; action text; personal boolean;
BEGIN
 u:=folha_privado.ator();PERFORM folha_privado.lock_dia(p,d);
 IF NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'TENANT_INTEGRITY_CONFLICT'; END IF;
 SELECT * INTO old FROM public.folha_avaliacoes_diarias WHERE empresa_id=u.empresa_id AND colaborador_id=p AND data=d FOR UPDATE;
 personal:=folha_privado.diaria_pessoal(p,d);
 IF NOT personal AND old.id IS NULL THEN RETURN NULL; END IF;
 f:=folha_privado.diaria_factos(p,d); hash:=encode(sha256(convert_to((f->'canonical')::text,'UTF8')),'hex');
 IF old.id IS NOT NULL AND old.factos_fingerprint=hash AND old.ativa=personal THEN RETURN to_jsonb(old); END IF;
 n:=old;
 IF old.id IS NULL THEN
  ref:=folha_privado.diaria_referencia(p,d);
  n.id:=gen_random_uuid();n.empresa_id:=u.empresa_id;n.colaborador_id:=p;n.data:=d;n.referencia_revision:=1;
  n.referencia_estado:=ref->>'referencia_estado';n.referencia_origem:=ref->>'referencia_origem';n.jornada_versao_id:=(ref->>'jornada_versao_id')::uuid;n.permanencia_id:=(ref->>'permanencia_id')::uuid;n.obra_origem_id:=(ref->>'obra_origem_id')::uuid;n.horario_versao_id:=(ref->>'horario_versao_id')::uuid;
  n.permanencia_snapshot:=nullif(ref->'permanencia_snapshot','null'::jsonb);n.horario_snapshot:=nullif(ref->'horario_snapshot','null'::jsonb);n.contexto_snapshot:=ref->'contexto_snapshot';
  n.expected_minutes:=(ref->>'expected_minutes')::integer;n.referencia_motivo:=ref->>'referencia_motivo';n.referencia_evidencia:=ref->'referencia_evidencia';
  IF n.referencia_estado='capturada' THEN n.capturado_por:=u.id;n.capturado_em:=now();n.captura_request_id:=req; END IF;
  n.criado_por:=u.id;n.criado_em:=now();n.request_id_inicial:=req;n.he_estado:='nenhum';
 END IF;
 n.ativa:=personal;n.modo_dia:=CASE WHEN NOT EXISTS(SELECT 1 FROM public.folha_registos r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.colaborador_id=p AND r.data=d AND x->>'mode'='personalizado') THEN 'normal_individual' WHEN (f->>'mixed')::boolean THEN 'misto' ELSE 'personalizado' END;n.revision:=coalesce(old.revision,0)+1;
 n.realizado_minutes:=(f->>'minutes')::integer;n.factos_fingerprint:=hash;n.factos_revisoes:=f->'revisions';n.fingerprint_version:='folha_factos_v1';n.regra_avaliacao_version:='diaria_v1';
 n.atualizado_por:=u.id;n.avaliado_por:=u.id;n.atualizado_em:=now();n.avaliado_em:=now();n.ultimo_request_id:=req;
 decision:=folha_privado.diaria_decisao_hash(hash,n.referencia_revision,n.horario_snapshot);
 IF old.he_estado IN('validada','nao_considerada') AND old.decisao_fingerprint IS DISTINCT FROM decision THEN
  INSERT INTO public.folha_gestao_historico(empresa_id,action,entidade_id,antes,depois,ator_id,request_id,reason) VALUES(u.empresa_id,'daily_he_invalidate',n.id,to_jsonb(old),jsonb_build_object('facts',hash),u.id,req,'Factos/referência alterados');
  n.he_estado:='nenhum';n.decisao_fingerprint:=NULL;n.he_decidido_por:=NULL;n.he_decidido_em:=NULL;n.he_motivo:=NULL;
 END IF;
 n.falta_minutes:=NULL;n.excedente_minutes:=NULL;
 IF n.referencia_estado='pendente' THEN pend:=array_append(pend,'referencia_diaria_pendente'); END IF;
 IF (f->>'open')::boolean THEN pend:=array_append(pend,'intervalo_aberto'); END IF;
 IF (f->>'conflict')::boolean THEN pend:=array_append(pend,'conflito_factos'); END IF;
 IF (f->>'special_pending')::boolean THEN pend:=array_append(pend,'dia_especial_pendente'); END IF;
 IF n.expected_minutes IS NOT NULL AND NOT (f->>'open')::boolean AND NOT (f->>'conflict')::boolean THEN
  n.falta_minutes:=greatest(0,n.expected_minutes-n.realizado_minutes);n.excedente_minutes:=greatest(0,n.realizado_minutes-n.expected_minutes);
  IF n.falta_minutes>0 THEN pend:=array_append(pend,'horas_em_falta'); END IF;
  IF n.excedente_minutes>0 THEN
   IF n.he_estado NOT IN('validada','nao_considerada') THEN n.he_estado:='pendente'; END IF;
   IF n.he_estado='pendente' THEN pend:=array_append(pend,'he_diaria_pendente'); END IF;
  ELSE n.he_estado:='nenhum'; END IF;
 ELSE n.he_estado:='nao_avaliavel'; END IF;
 IF n.he_estado NOT IN('validada','nao_considerada') THEN n.decisao_fingerprint:=NULL;n.he_decidido_por:=NULL;n.he_decidido_em:=NULL;n.he_motivo:=NULL; END IF;
 n.pendencias:=pend;
 n.estado:=CASE WHEN NOT personal THEN 'inativa' WHEN n.referencia_estado='pendente' THEN 'referencia_pendente' WHEN (f->>'conflict')::boolean THEN 'conflito' WHEN (f->>'open')::boolean THEN 'intervalo_aberto' WHEN n.falta_minutes>0 THEN 'horas_em_falta' WHEN n.excedente_minutes>0 AND n.he_estado NOT IN('validada','nao_considerada') THEN 'potencial_he' WHEN cardinality(pend)>0 THEN 'outras_pendencias' ELSE 'regular' END;
 action:=CASE WHEN old.id IS NULL THEN 'daily_evaluation_create' WHEN NOT personal THEN 'daily_evaluation_deactivate' WHEN NOT old.ativa THEN 'daily_evaluation_reactivate' ELSE 'daily_evaluation_recalculate' END;
 IF old.id IS NULL THEN INSERT INTO public.folha_avaliacoes_diarias SELECT (n).*;
 ELSE UPDATE public.folha_avaliacoes_diarias SET (ativa,modo_dia,revision,realizado_minutes,falta_minutes,excedente_minutes,estado,he_estado,pendencias,factos_revisoes,factos_fingerprint,decisao_fingerprint,he_decidido_por,he_decidido_em,he_motivo,atualizado_por,atualizado_em,avaliado_por,avaliado_em,ultimo_request_id) =
 (n.ativa,n.modo_dia,n.revision,n.realizado_minutes,n.falta_minutes,n.excedente_minutes,n.estado,n.he_estado,n.pendencias,n.factos_revisoes,n.factos_fingerprint,n.decisao_fingerprint,n.he_decidido_por,n.he_decidido_em,n.he_motivo,n.atualizado_por,n.atualizado_em,n.avaliado_por,n.avaliado_em,n.ultimo_request_id) WHERE id=n.id; END IF;
 INSERT INTO public.folha_gestao_historico(empresa_id,action,entidade_id,antes,depois,ator_id,request_id) VALUES(u.empresa_id,action,n.id,CASE WHEN old.id IS NOT NULL THEN to_jsonb(old) END,to_jsonb(n),u.id,req);
 RETURN to_jsonb(n);
END $$;
CREATE OR REPLACE FUNCTION folha_privado.conferencia_calcular(p uuid,m date) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $calculate$
DECLARE u public.utilizadores;c public.colaboradores;cfg public.folha_config_empresa;old public.folha_conferencias_mensais;ev public.folha_avaliacoes_diarias;ref jsonb;refs jsonb:='{}';s jsonb;f jsonb;ab jsonb;hs jsonb;pend jsonb:='[]';days jsonb:='[]';d date;limit_date date;worked integer;expected integer;total_actual integer:=0;total_known integer:=0;unknown integer:=0;credited integer:=0;absence_pending boolean;has_absence boolean;open_day boolean;
BEGIN
 u:=folha_privado.ator();SELECT * INTO c FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;
 IF m IS NULL OR NOT isfinite(m) OR extract(day FROM m) IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'MONTH_REQUIRED';END IF;
 SELECT * INTO cfg FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id;SELECT * INTO old FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=p AND competencia=m;
 limit_date:=(m+interval '1 month')::date;d:=greatest(m,c.data_admissao);IF c.data_admissao IS NULL THEN pend:=pend||jsonb_build_array(jsonb_build_object('reason','admissao_por_confirmar'));d:=m;END IF;
 IF NOT coalesce(cfg.calendar_complete,false) OR NOT extract(year FROM m)::integer=ANY(coalesce(cfg.calendar_validated_years,'{}')) THEN pend:=pend||jsonb_build_array(jsonb_build_object('reason','calendario_por_confirmar'));END IF;
 WHILE d<limit_date AND (c.data_saida IS NULL OR d<c.data_saida) LOOP
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',x.id,'revision',x.revision,'work_id',x.obra_id,'intervals',x.intervals,'minutes',x.minutes,'state',x.estado,'special_day',x.special_day,'special_reviewed',x.special_reviewed_at IS NOT NULL) ORDER BY x.id::text COLLATE "C"),'[]'),coalesce(sum(x.minutes),0)::integer,coalesce(bool_or(x.estado='open'),false) INTO f,worked,open_day FROM public.folha_registos x WHERE x.empresa_id=u.empresa_id AND x.colaborador_id=p AND x.data=d;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'type',a.tipo,'state',a.estado) ORDER BY a.id::text COLLATE "C"),'[]'),coalesce(bool_or(a.estado='ausente_pendente'),false) INTO ab,absence_pending FROM public.ausencias a WHERE a.colaborador_id=p AND a.data=d;has_absence:=jsonb_array_length(ab)>0;
  SELECT * INTO ev FROM public.folha_avaliacoes_diarias WHERE empresa_id=u.empresa_id AND colaborador_id=p AND data=d;
  ref:=old.referencias->d::text;
  IF ref->>'referencia_estado' IS DISTINCT FROM 'capturada' OR ref->>'source'='daily_frozen' AND (ref->>'reference_revision')::integer IS DISTINCT FROM ev.referencia_revision THEN
   IF ev.referencia_estado='capturada' THEN ref:=jsonb_build_object('referencia_estado','capturada','expected_minutes',ev.expected_minutes,'reference_revision',ev.referencia_revision,'source','daily_frozen','evaluation_id',ev.id,'snapshot',ev.horario_snapshot);
   ELSIF cfg.avaliacao_diaria_data_ativacao IS NOT NULL THEN ref:=folha_privado.diaria_referencia(p,d);
   ELSE ref:=jsonb_build_object('referencia_estado','pendente','expected_minutes',NULL,'reason','mecanismo_diario_nao_ativado');END IF;
  END IF;
  IF d<=(now() AT TIME ZONE 'Europe/Lisbon')::date THEN refs:=refs||jsonb_build_object(d::text,ref);END IF;expected:=CASE WHEN ref->>'referencia_estado'='capturada' THEN (ref->>'expected_minutes')::integer END;total_actual:=total_actual+worked;
  IF expected IS NULL THEN unknown:=unknown+1;pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','referencia_diaria_pendente'));ELSE total_known:=total_known+expected;END IF;
  IF open_day THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','intervalo_aberto'));END IF;
  IF absence_pending THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','ausencia_por_classificar'));END IF;
  IF has_absence AND worked>0 THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','ausencia_com_horas'));
  ELSIF has_absence AND NOT absence_pending AND expected IS NOT NULL THEN credited:=credited+expected;
  ELSIF expected>worked AND NOT open_day AND d<=(now() AT TIME ZONE 'Europe/Lisbon')::date THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','horas_em_falta','minutes',expected-worked));END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(f) x WHERE x->>'state'='regularization' AND NOT coalesce(ev.ativa,false)) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','factos_por_regularizar'));END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(f) x WHERE (x->>'special_day')::boolean AND NOT (x->>'special_reviewed')::boolean) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','dia_especial_pendente'));END IF;
  IF ev.ativa AND ev.factos_fingerprint IS DISTINCT FROM encode(sha256(convert_to((folha_privado.diaria_factos(p,d)->'canonical')::text,'UTF8')),'hex') THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','avaliacao_por_reconciliar'));END IF;
 IF ev.ativa THEN
   IF ev.he_estado='pendente' THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','he_por_classificar'));END IF;
   IF EXISTS(SELECT 1 FROM unnest(ev.pendencias) x WHERE x NOT IN('he_validada_aguarda_processamento','he_diaria_pendente','horas_em_falta','referencia_diaria_pendente')) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','avaliacao_diaria_pendente'));END IF;
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',h.id,'revision',h.revision,'state',h.estado,'minutes',h.minutes,'source_revision',h.folha_revision) ORDER BY h.id::text COLLATE "C"),'[]') INTO hs FROM public.folha_he h JOIN public.folha_registos x ON x.id=h.folha_id WHERE x.colaborador_id=p AND x.data=d AND h.empresa_id=u.empresa_id AND h.estado<>'superseded';
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(hs) h WHERE h->>'state' IN('potential','pending_validation','pending_rule')) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','he_normal_por_classificar'));END IF;
  IF EXISTS(SELECT 1 FROM public.ponto_pessoal_obra x WHERE x.empresa_id=u.empresa_id AND x.colaborador_id=p AND x.data=d) THEN pend:=pend||jsonb_build_array(jsonb_build_object('date',d,'reason','legado_por_reconciliar'));END IF;
  days:=days||jsonb_build_array(jsonb_build_object('date',d,'facts',f,'actual_minutes',worked,'expected_minutes',expected,'absence',ab,'normal_he',hs,'daily',CASE WHEN ev.id IS NULL THEN NULL ELSE jsonb_build_object('id',ev.id,'revision',ev.revision,'fingerprint',ev.factos_fingerprint,'reference_revision',ev.referencia_revision,'he_state',ev.he_estado,'he_quantity',ev.excedente_minutes,'decision_fingerprint',ev.decisao_fingerprint,'decided_by',ev.he_decidido_por,'decided_at',ev.he_decidido_em) END));d:=d+1;
 END LOOP;
 s:=jsonb_build_object('version','monthly_hr27_v1','company_id',u.empresa_id,'person_id',p,'month',m,'admission',c.data_admissao,'exit',c.data_saida,'calendar_complete',cfg.calendar_complete,'calendar_years',(SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(cfg.calendar_validated_years) x),'holiday_dates',(SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(cfg.holiday_dates) x),'references',refs,'days',days,'actual_minutes',total_actual,'known_expected_minutes',total_known,'expected_minutes',CASE WHEN unknown=0 THEN total_known END,'unknown_reference_days',unknown,'classified_absence_minutes',credited,'pending',pend,'he_policy','HR-27','financial_effect',false);
 RETURN s||jsonb_build_object('fingerprint',encode(sha256(convert_to(s::text,'UTF8')),'hex'));
END $calculate$;
CREATE OR REPLACE FUNCTION folha_privado.payroll_facts(p uuid,m date) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT jsonb_build_object('sheets',coalesce((SELECT jsonb_agg(jsonb_build_object('id',f.id,'revision',f.revision,'date',f.data,'minutes',f.minutes,'state',coalesce((SELECT CASE WHEN cardinality(array_remove(a.pendencias,'he_validada_aguarda_processamento'))=0 AND a.referencia_estado='capturada' AND a.falta_minutes=0 AND a.excedente_minutes IS NOT NULL AND a.he_estado IN('nenhum','validada','nao_considerada') THEN 'registered' ELSE 'regularization' END FROM public.folha_avaliacoes_diarias a WHERE a.colaborador_id=p AND a.data=f.data AND a.ativa),f.estado),'special_day',f.special_day,'special_reviewed',f.special_reviewed_at IS NOT NULL) ORDER BY f.data,f.id)
 FROM public.folha_registos f WHERE f.colaborador_id=p AND f.data>=m AND f.data<(m+interval '1 month')::date),'[]'),
 'absences',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'date',a.data,'type',a.tipo,'state',a.estado) ORDER BY a.data,a.id)
 FROM public.ausencias a WHERE a.colaborador_id=p AND a.data>=m AND a.data<(m+interval '1 month')::date),'[]'),
 'pending_days',coalesce((SELECT jsonb_agg(data ORDER BY data) FROM (SELECT DISTINCT q.data FROM public.quadro_pessoal_alocacao q WHERE q.colaborador_id=p AND q.data>=m AND q.data<(m+interval '1 month')::date AND q.data<=(now() AT TIME ZONE 'Europe/Lisbon')::date AND NOT EXISTS(SELECT 1 FROM public.folha_avaliacoes_diarias a WHERE a.colaborador_id=p AND a.data=q.data AND a.ativa) AND NOT EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.colaborador_id=p AND f.data=q.data AND f.obra_id IS NOT DISTINCT FROM q.obra_id) AND NOT EXISTS(SELECT 1 FROM public.ausencias a WHERE a.colaborador_id=p AND a.data=q.data) AND NOT EXISTS(SELECT 1 FROM public.ponto_pessoal_obra h WHERE h.colaborador_id=p AND h.data=q.data)) missing),'[]'),
 'legacy_days',coalesce((SELECT jsonb_agg(DISTINCT data ORDER BY data) FROM public.ponto_pessoal_obra WHERE colaborador_id=p AND data>=m AND data<(m+interval '1 month')::date),'[]'),
 'financial_effect',false,'legacy_not_converted',true)
 || CASE WHEN EXISTS(SELECT 1 FROM public.folha_avaliacoes_diarias a WHERE a.colaborador_id=p AND a.data>=m AND a.data<(m+interval '1 month')::date AND a.ativa) THEN
 jsonb_build_object('daily_evaluations',(SELECT jsonb_agg(jsonb_build_object('id',a.id,'date',a.data,'revision',a.revision,'reference_revision',a.referencia_revision,'fingerprint',a.factos_fingerprint,'state',a.estado,'expected_minutes',a.expected_minutes,'minutes',a.realizado_minutes,'he_state',a.he_estado,'pending',a.pendencias) ORDER BY a.data,a.id) FROM public.folha_avaliacoes_diarias a WHERE a.colaborador_id=p AND a.data>=m AND a.data<(m+interval '1 month')::date AND a.ativa)) ELSE '{}'::jsonb END
$$;
CREATE OR REPLACE FUNCTION public.fn_folha_relatorio_horas_v3(p_obra_id uuid,p_inicio date,p_fim date,p_kind text DEFAULT NULL,p_fornecedor_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $report$
DECLARE u public.utilizadores;records jsonb;legacy jsonb;days jsonb;weeks jsonb;months jsonb;
BEGIN
 u:=folha_privado.ator();IF p_obra_id IS NULL OR p_inicio IS NULL OR p_fim IS NULL OR p_fim<p_inicio OR p_fim-p_inicio>30 OR p_kind IS NOT NULL AND p_kind NOT IN('primeline','external') THEN RAISE EXCEPTION 'REPORT_RANGE_INVALID: até 31 dias';END IF;
 PERFORM folha_privado.obra(p_obra_id);
 IF p_fornecedor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fornecedores WHERE id=p_fornecedor_id AND empresa_id=u.empresa_id) THEN RAISE EXCEPTION 'PERMISSION_DENIED: fornecedor' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',f.id,'revision',f.revision,'date',f.data,'work_id',f.obra_id,'person_id',coalesce(f.colaborador_id,f.externo_id),'kind',CASE WHEN f.externo_id IS NULL THEN 'primeline' ELSE 'external' END,'name',coalesce(c.nome,e.nome),'provider_id',e.fornecedor_id,'provider_name',provider.nome,'intervals',f.intervals,'minutes',f.minutes,'open',f.estado='open','corrected',EXISTS(SELECT 1 FROM public.folha_historico h WHERE h.empresa_id=u.empresa_id AND h.person_id=coalesce(f.colaborador_id,f.externo_id) AND h.kind=CASE WHEN f.externo_id IS NULL THEN 'primeline' ELSE 'external' END AND h.obra_id=f.obra_id AND h.data=f.data AND h.antes IS NOT NULL AND h.antes<>'null'::jsonb),'last_changed_at',f.atualizado_em,'changed_by',f.atualizado_por) ORDER BY f.data,f.id),'[]') INTO records
 FROM public.folha_registos f LEFT JOIN public.colaboradores c ON c.id=f.colaborador_id AND c.empresa_id=u.empresa_id LEFT JOIN public.folha_externos e ON e.id=f.externo_id AND e.empresa_id=u.empresa_id LEFT JOIN public.fornecedores provider ON provider.id=e.fornecedor_id AND provider.empresa_id=u.empresa_id
 WHERE f.empresa_id=u.empresa_id AND f.obra_id=p_obra_id AND f.data BETWEEN p_inicio AND p_fim AND (p_kind IS NULL OR p_kind='primeline' AND f.colaborador_id IS NOT NULL OR p_kind='external' AND f.externo_id IS NOT NULL) AND (p_fornecedor_id IS NULL OR e.fornecedor_id=p_fornecedor_id);
 SELECT coalesce(jsonb_agg(jsonb_build_object('source','legacy','original',to_jsonb(p)) ORDER BY p.data,p.id),'[]') INTO legacy FROM public.ponto_pessoal_obra p WHERE p.empresa_id=u.empresa_id AND p.obra_id=p_obra_id AND p.data BETWEEN p_inicio AND p_fim AND p_kind IS DISTINCT FROM 'external' AND p_fornecedor_id IS NULL;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.date,x.person_id),'[]') INTO days FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,r->>'date' date,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',r->>'date') x;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.week,x.person_id),'[]') INTO weeks FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,date_trunc('week',(r->>'date')::date)::date week,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',date_trunc('week',(r->>'date')::date)::date) x;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.month_start,x.person_id),'[]') INTO months FROM (SELECT r->>'person_id' person_id,r->>'kind' kind,date_trunc('month',(r->>'date')::date)::date month_start,sum((r->>'minutes')::integer)::integer minutes FROM jsonb_array_elements(records) r GROUP BY r->>'person_id',r->>'kind',date_trunc('month',(r->>'date')::date)::date) x;
 RETURN jsonb_build_object('version',3,'committed',false,'work_id',p_obra_id,'from',p_inicio,'to',p_fim,'records',records,'daily',days,'weekly',weeks,'monthly',months,'legacy',legacy,'legacy_included_in_totals',false,'financial_effect',false,'classification_included',false);
END $report$;
CREATE OR REPLACE FUNCTION public.fn_folha_conferencia_v3(p_acao text,p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $rpc$
DECLARE u public.utilizadores;p uuid;m date;req uuid;c public.folha_conferencias_mensais;op folha_privado.operacoes;s jsonb;before jsonb;after jsonb;payload jsonb;token text;outcome jsonb;reason text;requests jsonb;
BEGIN
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();SELECT * INTO u FROM public.utilizadores WHERE id=u.id AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND OR NOT folha_privado.adm() THEN RAISE EXCEPTION 'PERMISSION_DENIED: conferência mensal' USING ERRCODE='42501';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 p:=(p_dados->>'person_id')::uuid;m:=(p_dados->>'month')::date;req:=(p_dados->>'request_id')::uuid;reason:=nullif(btrim(p_dados->>'reason'),'');
 IF p_acao IS NULL OR p_acao NOT IN('conferir','devolver','validar') OR p_dados->>'version' IS DISTINCT FROM '3' OR p_confirmar IS NULL OR req IS NULL OR m IS NULL OR NOT isfinite(m) OR extract(day FROM m) IS DISTINCT FROM 1 OR length(reason)>1000 THEN RAISE EXCEPTION 'VALIDATION_ERROR: competência';END IF;
 IF p_dados->>'work_id' IS NOT NULL OR p_dados ? 'company_id' AND p_dados->>'company_id' IS DISTINCT FROM u.empresa_id::text OR p_dados ? 'empresa_id' AND p_dados->>'empresa_id' IS DISTINCT FROM u.empresa_id::text THEN RAISE EXCEPTION 'PERMISSION_DENIED: âmbito mensal' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(u.empresa_id::text||':'||p::text||':'||m::text,0));PERFORM pg_advisory_xact_lock(hashtextextended(u.empresa_id::text||':'||u.id::text||':'||req::text,0));
 payload:=jsonb_build_object('action','monthly_'||p_acao,'data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 SELECT * INTO c FROM public.folha_conferencias_mensais WHERE empresa_id=u.empresa_id AND colaborador_id=p AND competencia=m FOR UPDATE;
 IF (p_dados->>'expected_revision')::integer IS DISTINCT FROM coalesce(c.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 s:=folha_privado.conferencia_calcular(p,m);before:=CASE WHEN c.id IS NULL THEN NULL ELSE to_jsonb(c) END;
 IF p_acao='validar' THEN
  IF c.id IS NULL OR c.estado<>'conferida' OR c.fingerprint IS DISTINCT FROM s->>'fingerprint' THEN RAISE EXCEPTION 'MONTHLY_FACTS_NOT_CONFERRED' USING ERRCODE='40001';END IF;
  IF (m+interval '1 month')::date>(now() AT TIME ZONE 'Europe/Lisbon')::date THEN RAISE EXCEPTION 'COMPETENCIA_EM_CURSO';END IF;
  IF jsonb_array_length(s->'pending')>0 OR jsonb_array_length(c.pedidos_correcao)>0 THEN RAISE EXCEPTION 'MONTHLY_PENDING_FACTS';END IF;
 ELSIF p_acao='devolver' THEN
  requests:=p_dados->'records';IF reason IS NULL OR jsonb_typeof(requests) IS DISTINCT FROM 'array' OR jsonb_array_length(requests) NOT BETWEEN 1 AND 124 THEN RAISE EXCEPTION 'CORRECTION_REASON_RECORDS_REQUIRED';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(requests) x WHERE NOT EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.id=(x->>'id')::uuid AND f.empresa_id=u.empresa_id AND f.colaborador_id=p AND f.data>=m AND f.data<(m+interval '1 month')::date AND f.revision=(x->>'revision')::integer)) OR EXISTS(SELECT 1 FROM jsonb_array_elements(requests) x GROUP BY x->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'STALE_SOURCE' USING ERRCODE='40001';END IF;
 ELSE
  IF c.id IS NOT NULL AND jsonb_array_length(c.pedidos_correcao)>0 AND reason IS NULL THEN RAISE EXCEPTION 'CORRECTION_ACKNOWLEDGEMENT_REASON_REQUIRED';END IF;
  requests:='[]';
 END IF;
 after:=jsonb_build_object('state',CASE p_acao WHEN 'conferir' THEN 'conferida' WHEN 'devolver' THEN 'devolvida' ELSE 'validada_para_integracao' END,'snapshot',s,'requests',coalesce(requests,'[]'::jsonb));
 token:=encode(sha256(convert_to(jsonb_build_object('actor_id',u.id,'company_id',u.empresa_id,'payload',payload,'before',before,'after',after)::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'preview',after);END IF;
 IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 IF c.id IS NULL THEN
  INSERT INTO public.folha_conferencias_mensais(empresa_id,colaborador_id,competencia,estado,revision,referencias,snapshot,fingerprint,pedidos_correcao,criado_por,atualizado_por,ultimo_request_id)
  VALUES(u.empresa_id,p,m,after->>'state',1,s->'references',s,s->>'fingerprint',after->'requests',u.id,u.id,req) RETURNING * INTO c;
 ELSE
  UPDATE public.folha_conferencias_mensais SET estado=after->>'state',revision=revision+1,referencias=s->'references',snapshot=s,fingerprint=s->>'fingerprint',pedidos_correcao=after->'requests',validacao_fingerprint=CASE WHEN p_acao='validar' THEN s->>'fingerprint' ELSE validacao_fingerprint END,validado_por=CASE WHEN p_acao='validar' THEN u.id ELSE validado_por END,validado_em=CASE WHEN p_acao='validar' THEN now() ELSE validado_em END,atualizado_por=u.id,atualizado_em=now(),ultimo_request_id=req WHERE id=c.id RETURNING * INTO c;
 END IF;
 INSERT INTO public.folha_conferencia_historico(empresa_id,conferencia_id,revision,action,antes,depois,ator_id,request_id,reason) VALUES(u.empresa_id,c.id,c.revision,p_acao,before,to_jsonb(c),u.id,req,reason);
 outcome:=jsonb_build_object('version',3,'committed',true,'request_id',req,'revision',c.revision,'conference',to_jsonb(c),'financial_effect',false);
 INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,outcome,now());RETURN outcome;
END $rpc$;
CREATE OR REPLACE FUNCTION public.fn_folha_dia_normal_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $normalbatch$
DECLARE u public.utilizadores;req uuid:=(p_dados->>'request_id')::uuid;w uuid:=(p_dados->>'work_id')::uuid;d date:=(p_dados->>'date')::date;person jsonb;child jsonb;preview jsonb;previews jsonb:='[]';outcomes jsonb:='[]';token text;payload jsonb;op folha_privado.operacoes;outcome jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;
 IF req IS NULL OR d IS NULL OR w IS NULL OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR jsonb_typeof(p_dados->'people') IS DISTINCT FROM 'array' OR jsonb_array_length(p_dados->'people') NOT BETWEEN 1 AND 100 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_dados->'people') x GROUP BY x->>'kind',x->>'person_id' HAVING count(*)>1) THEN RAISE EXCEPTION 'NORMAL_BATCH_INVALID';END IF;
 FOR person IN SELECT value FROM jsonb_array_elements(p_dados->'people') ORDER BY value->>'kind',value->>'person_id' LOOP
  PERFORM folha_privado.destino_autorizar_v3((person->>'person_id')::uuid,w,person->>'kind',true);PERFORM folha_privado.lock_dia((person->>'person_id')::uuid,d);
  IF person->>'kind'='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=(person->>'person_id')::uuid AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR UPDATE;ELSE PERFORM 1 FROM public.folha_externos WHERE id=(person->>'person_id')::uuid AND empresa_id=u.empresa_id AND ativo FOR UPDATE;END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: pessoa' USING ERRCODE='42501';END IF;
 END LOOP;
 payload:=jsonb_build_object('action','normal_batch','data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 FOR person IN SELECT value FROM jsonb_array_elements(p_dados->'people') ORDER BY value->>'kind',value->>'person_id' LOOP
  IF EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.data=d AND CASE WHEN person->>'kind'='primeline' THEN f.colaborador_id=(person->>'person_id')::uuid ELSE f.externo_id=(person->>'person_id')::uuid END) THEN RAISE EXCEPTION 'NORMAL_DAY_ALREADY_REGISTERED: não substituir factos';END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(person->'intervals') x WHERE x->>'mode' IS DISTINCT FROM 'normal') THEN RAISE EXCEPTION 'NORMAL_BATCH_INVALID';END IF;
  child:=jsonb_build_object('version',3,'request_id',md5(req::text||':'||(person->>'kind')||':'||(person->>'person_id'))::uuid,'work_id',w,'date',d,'kind',person->>'kind','person_id',person->>'person_id','expected_revision',0,'expected_daily_revision',person->'expected_daily_revision','intervals',person->'intervals','reason',p_dados->>'reason');
  preview:=public.fn_folha_destino_operar_v3(child,false,NULL);previews:=previews||jsonb_build_array(jsonb_build_object('body',child,'token',preview->>'versao'));
 END LOOP;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'previews',previews)::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'people_count',jsonb_array_length(previews));END IF;
 IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 FOR preview IN SELECT value FROM jsonb_array_elements(previews) LOOP outcomes:=outcomes||jsonb_build_array(public.fn_folha_destino_operar_v3(preview->'body',true,preview->>'token'));END LOOP;
 outcome:=jsonb_build_object('version',3,'committed',true,'request_id',req,'results',outcomes);INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,outcome,now());RETURN outcome;
END $normalbatch$;
CREATE OR REPLACE FUNCTION public.fn_folha_faltou_v2(p_acao text,p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $rpc$
DECLARE u public.utilizadores;p uuid;w uuid;d date;req uuid;ab public.ausencias;op folha_privado.operacoes;payload jsonb;token text;before jsonb;after jsonb;result jsonb;reason text;choice text;today date:=(now() AT TIME ZONE 'Europe/Lisbon')::date;
BEGIN
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);
 u:=folha_privado.ator();SELECT * INTO u FROM public.utilizadores WHERE id=u.id AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 req:=(p_dados->>'request_id')::uuid;reason:=nullif(btrim(p_dados->>'reason'),'');
 IF p_confirmar IS NULL OR p_dados->>'version' IS DISTINCT FROM '2' OR req IS NULL OR p_acao IS NULL OR p_acao NOT IN('absence_report','absence_classify') OR length(reason)>1000 THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;
 IF p_dados ? 'empresa_id' AND p_dados->>'empresa_id' IS DISTINCT FROM u.empresa_id::text THEN RAISE EXCEPTION 'PERMISSION_DENIED: tenant' USING ERRCODE='42501';END IF;
 IF p_acao='absence_report' THEN
  p:=(p_dados->'key'->>'person_id')::uuid;w:=(p_dados->>'work_id')::uuid;d:=(p_dados->>'date')::date;
  IF u.funcao<>'encarregado' OR w IS NULL OR p IS NULL OR p_dados->'key'->>'kind' IS DISTINCT FROM 'primeline' THEN RAISE EXCEPTION 'PERMISSION_DENIED: equipa Primeline do Encarregado' USING ERRCODE='42501';END IF;
  IF p_dados ? 'choice' OR p_dados ? 'classification' THEN RAISE EXCEPTION 'FALTOU_NEUTRAL_REPORT_ONLY';END IF;
  IF p_dados->'key'->>'work_id' IS DISTINCT FROM w::text OR p_dados->'key'->>'date' IS DISTINCT FROM d::text THEN RAISE EXCEPTION 'VALIDATION_ERROR: chave';END IF;
  IF d IS NULL OR d NOT BETWEEN today-1 AND today THEN RAISE EXCEPTION 'DATE_WINDOW: apenas hoje e ontem';END IF;
  PERFORM folha_privado.obra(w,true);
  PERFORM 1 FROM public.colaboradores c WHERE c.id=p AND c.empresa_id=u.empresa_id AND c.data_admissao<=d AND (c.data_saida IS NULL OR c.data_saida>d) AND c.utilizador_id IS DISTINCT FROM u.id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador' USING ERRCODE='42501';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.quadro_equipa_permanencias m WHERE m.colaborador_id=p AND m.obra_id=w AND m.empresa_id=u.empresa_id AND m.inicio<=d AND (m.fim IS NULL OR m.fim>d)) THEN RAISE EXCEPTION 'PERMISSION_DENIED: fora da equipa' USING ERRCODE='42501';END IF;
 ELSE
  IF NOT folha_privado.adm() OR p_dados->>'work_id' IS NOT NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: classificação administrativa' USING ERRCODE='42501';END IF;
  SELECT a.* INTO ab FROM public.ausencias a JOIN public.colaboradores c ON c.id=a.colaborador_id AND c.empresa_id=u.empresa_id WHERE a.id=(p_dados->>'id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: ausência' USING ERRCODE='42501';END IF;
  p:=ab.colaborador_id;d:=ab.data;choice:=p_dados->>'classification';
  IF choice IS NULL OR choice NOT IN('falta_injustificada','falta_justificada_com_remuneracao','falta_justificada_sem_remuneracao') OR reason IS NULL THEN RAISE EXCEPTION 'CLASSIFICATION_REASON_REQUIRED';END IF;
 END IF;
 PERFORM folha_privado.lock_dia(p,d);PERFORM pg_advisory_xact_lock(hashtextextended(u.empresa_id::text||':'||u.id::text||':'||req::text,0));
 payload:=jsonb_build_object('action',p_acao,'data',p_dados);
 SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN
  IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;
  IF NOT p_confirmar THEN RETURN jsonb_build_object('version',2,'committed',false,'versao',op.token);END IF;
  IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;
 END IF;
 IF EXISTS(SELECT 1 FROM public.folha_registos WHERE colaborador_id=p AND data=d) OR EXISTS(SELECT 1 FROM public.ponto_pessoal_obra WHERE colaborador_id=p AND data=d) OR EXISTS(SELECT 1 FROM public.lancamentos_mao_obra WHERE colaborador_id=p AND data=d) OR EXISTS(SELECT 1 FROM public.horas_extraordinarias WHERE colaborador_id=p AND data=d) THEN RAISE EXCEPTION 'POINT_CONFLICT: já existe ponto ou horas; regularização administrativa necessária';END IF;
 IF p_acao='absence_report' THEN
  IF EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=p AND data=d) THEN RAISE EXCEPTION 'ABSENCE_CONFLICT';END IF;
  IF folha_privado.linha(p,w,d,'primeline')->>'conflict' IS NOT NULL THEN RAISE EXCEPTION 'POINT_CONFLICT';END IF;
  before:='null'::jsonb;after:=jsonb_build_object('colaborador_id',p,'data',d,'tipo','falta_reportada_pendente','estado','ausente_pendente');
 ELSE
  SELECT * INTO ab FROM public.ausencias WHERE id=(p_dados->>'id')::uuid FOR UPDATE;
  IF ab.tipo<>'falta_reportada_pendente' OR ab.estado<>'ausente_pendente' OR p_dados->>'expected_type' IS DISTINCT FROM ab.tipo OR p_dados->>'expected_state' IS DISTINCT FROM ab.estado THEN RAISE EXCEPTION 'STALE_REVISION: ocorrência alterada' USING ERRCODE='40001';END IF;
  before:=to_jsonb(ab);after:=jsonb_build_object('tipo',choice,'estado',CASE WHEN choice='falta_justificada_sem_remuneracao' THEN 'justificada' ELSE 'confirmada' END,'reason',reason);
 END IF;
 token:=encode(sha256(convert_to(jsonb_build_object('actor_id',u.id,'company_id',u.empresa_id,'payload',payload,'before',before,'after',after)::text,'UTF8')),'hex');
 IF NOT p_confirmar THEN RETURN jsonb_build_object('version',2,'committed',false,'versao',token,'preview',after);END IF;
 IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 IF p_acao='absence_report' THEN
  INSERT INTO public.ausencias(colaborador_id,data,tipo,estado,comentario) VALUES(p,d,'falta_reportada_pendente','ausente_pendente',coalesce(reason,'Faltou — aguarda classificação administrativa')) RETURNING * INTO ab;
 ELSE
  UPDATE public.ausencias SET tipo=after->>'tipo',estado=after->>'estado',comentario=reason WHERE id=ab.id RETURNING * INTO ab;
 END IF;
 INSERT INTO public.folha_historico(empresa_id,obra_id,tipo_local,person_id,kind,data,action,antes,depois,revision,ator_id,request_id,reason)
 VALUES(u.empresa_id,w,CASE WHEN w IS NULL THEN 'escritorio' ELSE 'obra' END,p,'primeline',d,p_acao,before,to_jsonb(ab),1,u.id,req,reason);
 result:=jsonb_build_object('version',2,'committed',true,'request_id',req,'absence',to_jsonb(ab),'changed_keys',jsonb_build_array(jsonb_build_object('kind','primeline','person_id',p,'work_id',w,'date',d)));
 INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,result,now());RETURN result;
END $rpc$;
CREATE OR REPLACE FUNCTION public.fn_folha_externos_confirmar_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $confirm$
DECLARE u public.utilizadores;req uuid:=(p_dados->>'request_id')::uuid;w uuid:=(p_dados->>'work_id')::uuid;provider uuid:=(p_dados->>'provider_id')::uuid;m date:=(p_dados->>'month')::date;old public.folha_externos_confirmacoes;n public.folha_externos_confirmacoes;r jsonb;payload jsonb;token text;result jsonb;op folha_privado.operacoes;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();
 IF u.funcao<>'diretor_obra' THEN RAISE EXCEPTION 'PERMISSION_DENIED: confirmação do Diretor' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.obras WHERE id=w AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.obra_responsaveis WHERE obra_id=w AND utilizador_id=u.id AND papel='diretor_obra' FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;
 IF req IS NULL OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR provider IS NULL OR m IS NULL THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_dados) x WHERE x NOT IN('version','request_id','work_id','provider_id','month','expected_revision','reason')) THEN RAISE EXCEPTION 'UNKNOWN_FIELD';END IF;
 payload:=jsonb_build_object('action','external_confirm','data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 PERFORM 1 FROM public.folha_registos f JOIN public.folha_externos e ON e.id=f.externo_id WHERE f.empresa_id=u.empresa_id AND f.obra_id=w AND e.fornecedor_id=provider AND f.data>=m AND f.data<(m+interval '1 month')::date FOR SHARE OF f;
 SELECT * INTO old FROM public.folha_externos_confirmacoes WHERE empresa_id=u.empresa_id AND obra_id=w AND fornecedor_id=provider AND competencia=m ORDER BY revision DESC LIMIT 1 FOR UPDATE;
 IF (p_dados->>'expected_revision')::integer IS DISTINCT FROM coalesce(old.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 IF old.id IS NOT NULL AND nullif(btrim(p_dados->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED';END IF;
 r:=folha_privado.externo_mes_v3(w,provider,m);IF EXISTS(SELECT 1 FROM jsonb_array_elements(r->'records') x WHERE (x->>'open')::boolean) THEN RAISE EXCEPTION 'EXTERNAL_OPEN_INTERVALS';END IF;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'before',to_jsonb(old),'source',r)::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'preview',r);END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 INSERT INTO public.folha_externos_confirmacoes(empresa_id,obra_id,fornecedor_id,competencia,revision,facts_fingerprint,snapshot,confirmado_por,request_id,reason) VALUES(u.empresa_id,w,provider,m,coalesce(old.revision,0)+1,r->>'facts_fingerprint',r,u.id,req,p_dados->>'reason') RETURNING * INTO n;
 result:=jsonb_build_object('version',3,'committed',true,'request_id',req,'confirmation_id',n.id,'revision',n.revision,'facts_fingerprint',n.facts_fingerprint);INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,result,now());RETURN result;
END $confirm$;
CREATE OR REPLACE FUNCTION public.fn_folha_destino_operar_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $destination$
DECLARE u public.utilizadores;p uuid:=(p_dados->>'person_id')::uuid;w uuid:=(p_dados->>'work_id')::uuid;d date:=(p_dados->>'date')::date;k text:=p_dados->>'kind';req uuid:=(p_dados->>'request_id')::uuid;xs jsonb;all_xs jsonb;plan jsonb;before jsonb;daily jsonb;preview jsonb;data jsonb;payload jsonb;token text;outcome jsonb;op folha_privado.operacoes;result public.folha_registos;day_count integer;
BEGIN
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);
 u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM folha_privado.destino_autorizar_v3(p,w,k,true);PERFORM folha_privado.lock_dia(p,d);
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 IF req IS NULL OR p IS NULL OR d IS NULL OR k IS NULL OR k NOT IN('primeline','external') OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR p_confirmar IS NULL OR jsonb_typeof(p_dados->'intervals') IS DISTINCT FROM 'array' OR jsonb_array_length(p_dados->'intervals') NOT BETWEEN 1 AND 16 THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_dados) key WHERE key NOT IN('version','request_id','person_id','work_id','date','kind','intervals','expected_revision','expected_daily_revision','reason','note')) THEN RAISE EXCEPTION 'UNKNOWN_FIELD';END IF;
 IF k='external' AND u.funcao='diretor_obra' AND nullif(btrim(p_dados->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED';END IF;
 IF d<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 AND NOT folha_privado.adm_operacional() AND NOT(k='external' AND u.funcao='diretor_obra') THEN RAISE EXCEPTION 'CORRECTION_WINDOW_EXCEEDED';END IF;
 IF d<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 AND nullif(btrim(p_dados->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED';END IF;
 IF k='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR UPDATE;ELSE PERFORM 1 FROM public.folha_externos WHERE id=p AND empresa_id=u.empresa_id AND (ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.externo_id=p AND f.obra_id=w AND f.data=d AND f.empresa_id=u.empresa_id)) FOR UPDATE;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: pessoa' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.obras WHERE id=w AND situacao<>'em_curso') AND NOT EXISTS(SELECT 1 FROM public.folha_registos stored WHERE stored.obra_id=w AND stored.data=d AND CASE WHEN k='primeline' THEN stored.colaborador_id=p ELSE stored.externo_id=p END) THEN RAISE EXCEPTION 'DESTINATION_NOT_ACTIVE: usar referência de Garantia';END IF;
 payload:=jsonb_build_object('action','destination_save','data',p_dados);
 SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN
  IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;
  IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;
  IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;
 END IF;
 IF EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END AND f.empresa_id<>u.empresa_id) THEN RAISE EXCEPTION 'TENANT_INTEGRITY_CONFLICT';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_dados->'intervals') x WHERE x->>'mode' IS NULL OR x->>'mode' NOT IN('normal','personalizado') OR (x->>'mode'='personalizado' AND x->>'period' IS NOT NULL) OR (x->>'mode'='normal' AND coalesce(x->>'period','') NOT IN('manha','tarde')) OR x ? 'daily_scope') THEN RAISE EXCEPTION 'PERIOD_REQUIRED';END IF;
 SELECT jsonb_agg(CASE WHEN k='primeline' THEN x||jsonb_build_object('daily_scope',true) ELSE x END ORDER BY n) INTO xs FROM jsonb_array_elements(p_dados->'intervals') WITH ORDINALITY t(x,n);
 SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.id),'[]') INTO before FROM public.folha_registos f WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END;
 SELECT coalesce(jsonb_agg(x),'[]') INTO all_xs FROM public.folha_registos f CROSS JOIN LATERAL jsonb_array_elements(f.intervals) x WHERE f.data=d AND f.obra_id IS DISTINCT FROM w AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END;
 all_xs:=all_xs||xs;IF jsonb_array_length(all_xs)>16 THEN RAISE EXCEPTION 'INTERVAL_LIMIT';END IF;PERFORM folha_privado.facts(all_xs,d);
 SELECT count(*) INTO day_count FROM public.folha_registos f WHERE f.data=d AND f.obra_id IS DISTINCT FROM w AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END;
 IF day_count>=4 THEN RAISE EXCEPTION 'DESTINATION_LIMIT';END IF;
 IF k='primeline' THEN
  SELECT to_jsonb(a) INTO daily FROM public.folha_avaliacoes_diarias a WHERE a.empresa_id=u.empresa_id AND a.colaborador_id=p AND a.data=d FOR UPDATE;
  IF (p_dados->>'expected_daily_revision')::integer IS DISTINCT FROM coalesce((daily->>'revision')::integer,0) THEN RAISE EXCEPTION 'STALE_REVISION: diária' USING ERRCODE='40001';END IF;
  IF EXISTS(SELECT 1 FROM public.folha_he h JOIN public.folha_registos f ON f.id=h.folha_id WHERE f.colaborador_id=p AND f.data=d) THEN RAISE EXCEPTION 'NORMAL_HE_REQUIRES_ADMIN_REVIEW';END IF;
 END IF;
 data:=jsonb_build_object('key',jsonb_build_object('kind',k,'person_id',p,'work_id',w,'date',d),'intervals',xs,'expected_revision',p_dados->'expected_revision','reason',p_dados->>'reason','note',p_dados->>'note');
 plan:=jsonb_build_array(jsonb_build_object('work_id',w,'intervals',xs));
 preview:=folha_privado.save_destino_v3(data,w,d,req,false,plan);
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'before',before,'daily',daily,'preview',preview,'reference',CASE WHEN k='primeline' AND daily IS NULL THEN folha_privado.diaria_referencia(p,d) END)::text,'UTF8')),'hex');
 IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'preview',jsonb_build_object('work_id',w,'person_id',p,'intervals',xs,'minutes',preview->'facts'->'minutes'));END IF;
 IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 PERFORM folha_privado.save_destino_v3(data,w,d,req,true,plan);
 SELECT * INTO result FROM public.folha_registos f WHERE f.empresa_id=u.empresa_id AND f.obra_id=w AND f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END;
 outcome:=jsonb_build_object('version',3,'committed',true,'request_id',req,'record',to_jsonb(result),'changed_keys',jsonb_build_array(jsonb_build_object('kind',k,'person_id',p,'work_id',w,'date',d)));
 INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,outcome,now());RETURN outcome;
END $destination$;DROP TABLE public.folha_referencias_historico;
DROP TABLE public.folha_referencias;DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.destino_autorizar_v3(uuid,uuid,text,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='c874fba357c974db5241fc0c5c82bf92a2f012e822f8d0fb545b0f18317daa22' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.destino_autorizar_v3(uuid,uuid,text,boolean)';END IF;END $functions$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
